        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    function getBarLabelPosition(dataIndex: number): string {
        const seriesModel = chart.getModel().getSeriesByIndex(0);
        const el = seriesModel.getData().getItemGraphicEl(dataIndex) as Element;
        return el.textConfig.position as string;
    }

    it('vertical bar, zero height, y axis not inverse -> top', function () {
        chart.setOption({
            xAxis: { type: 'category', data: ['a', 'b', 'c'] },
            yAxis: { type: 'value' },
            series: [{
                type: 'bar',
                data: [10, 0, -5],
                label: { show: true, position: 'outside' }
            }]
        });
        expect(getBarLabelPosition(0)).toEqual('top');    // positive value
        expect(getBarLabelPosition(1)).toEqual('top');    // zero value
        expect(getBarLabelPosition(2)).toEqual('bottom'); // negative value
    });

    it('vertical bar, zero height, y axis inverse -> bottom', function () {
        chart.setOption({
            xAxis: { type: 'category', data: ['a', 'b', 'c'] },
            yAxis: { type: 'value', inverse: true },
            series: [{
                type: 'bar',
                data: [10, 0, -5],
                label: { show: true, position: 'outside' }
            }]
        });
        expect(getBarLabelPosition(0)).toEqual('bottom');
        expect(getBarLabelPosition(1)).toEqual('bottom'); // zero value
        expect(getBarLabelPosition(2)).toEqual('top');
    });

    it('horizontal bar, zero width, x axis not inverse -> right', function () {
        chart.setOption({
            xAxis: { type: 'value' },
            yAxis: { type: 'category', data: ['a', 'b', 'c'] },
            series: [{
                type: 'bar',
                data: [10, 0, -5],
                label: { show: true, position: 'outside' }
            }]
        });
        expect(getBarLabelPosition(0)).toEqual('right'); // positive value
        expect(getBarLabelPosition(1)).toEqual('right'); // zero value
        expect(getBarLabelPosition(2)).toEqual('left');  // negative value
    });

    it('horizontal bar, zero width, x axis inverse -> left', function () {
        chart.setOption({
            xAxis: { type: 'value', inverse: true },
            yAxis: { type: 'category', data: ['a', 'b', 'c'] },
            series: [{
                type: 'bar',
                data: [10, 0, -5],
                label: { show: true, position: 'outside' }
            }]
        });
        expect(getBarLabelPosition(0)).toEqual('left');
        expect(getBarLabelPosition(1)).toEqual('left');  // zero value
        expect(getBarLabelPosition(2)).toEqual('right');
    });
});

